'use strict';

const { ExprError } = require('./errors');

const PAIRS = new Set(['**', '//', '<=', '>=', '==', '!=']);
const SINGLES = new Set(['+', '-', '*', '/', '%', '<', '>', '(', ')', ',']);
const WHITESPACE = /\s/;

/**
 * Create a lazy lexer over source. Tokens are produced on demand so that
 * errors are reported in source order (a syntax error before an invalid
 * character wins). Columns are 1-based offsets of each token's first char.
 */
function createLexer(source) {
  const number = /(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?/y;
  const identifier = /[A-Za-z_][A-Za-z0-9_]*/y;
  let offset = 0;

  function next() {
    while (offset < source.length && WHITESPACE.test(source[offset])) offset += 1;
    const column = offset + 1;
    if (offset === source.length) return { type: 'eof', value: '', column };
    number.lastIndex = offset;
    const numeric = number.exec(source);
    if (numeric) {
      offset = number.lastIndex;
      return { type: 'number', value: Number(numeric[0]), column };
    }
    identifier.lastIndex = offset;
    const name = identifier.exec(source);
    if (name) {
      offset = identifier.lastIndex;
      return { type: 'identifier', value: name[0], column };
    }
    const pair = source.slice(offset, offset + 2);
    if (PAIRS.has(pair)) {
      offset += 2;
      return { type: 'operator', value: pair, column };
    }
    if (SINGLES.has(source[offset])) {
      offset += 1;
      return { type: 'operator', value: source[offset - 1], column };
    }
    throw new ExprError('Unexpected character', column);
  }

  return { next };
}

module.exports = { createLexer };

