'use strict';

const { ExprError } = require('./errors');

const PAIRS = new Set(['**', '//', '<=', '>=', '==', '!=']);
const SINGLES = new Set(['+', '-', '*', '/', '%', '<', '>', '(', ')', ',']);
const WHITESPACE = /\s/;

/**
 * Create a lazy lexer over source. Tokens are produced on demand so that
 * errors are reported in source order (a syntax error before an invalid
 * character wins). Columns are 1-based offsets of each token's first char.
 */
function createLexer(source) {
  const number = /(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?/y;
  const identifier = /[A-Za-z_][A-Za-z0-9_]*/y;
  let offset = 0;

  function next() {
    while (offset < source.length && WHITESPACE.test(source[offset])) offset += 1;
    const column = offset + 1;
    if (offset === source.length) return { type: 'eof', value: '', column };
    number.lastIndex = offset;
    const numeric = number.exec(source);
    if (numeric) {
      offset = number.lastIndex;
      return { type: 'number', value: Number(numeric[0]), column };
    }
    identifier.lastIndex = offset;
    const name = identifier.exec(source);
    if (name) {
      offset = identifier.lastIndex;
      return { type: 'identifier', value: name[0], column };
    }
    const pair = source.slice(offset, offset + 2);
    if (PAIRS.has(pair)) {
      offset += 2;
      return { type: 'operator', value: pair, column };
    }
    if (SINGLES.has(source[offset])) {
      offset += 1;
      return { type: 'operator', value: source[offset - 1], column };
    }
    throw new ExprError('Unexpected character', column);
  }

  return { next };
}

module.exports = { createLexer };

'use strict';

const { ExprError } = require('./errors');
const { createLexer } = require('./tokenizer');

const COMPARISONS = new Set(['<', '<=', '>', '>=', '==', '!=']);
const PRODUCTS = new Set(['*', '/', '//', '%']);
const BUILTINS = new Set(['min', 'max', 'abs']);

/** Parse a complete source string into an AST. Nodes retain operator columns. */
function parse(source) {
  const lexer = createLexer(source);
  let token = lexer.next();
  const take = () => {
    const taken = token;
    token = lexer.next();
    return taken;
  };
  const isOperator = value => token.type === 'operator' && token.value === value;
  const expect = value => {
    if (!isOperator(value)) throw new ExprError(`Expected ${value}`, token.column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  // comparison := sum (cmp sum)*  — chained, not nested.
  function comparison() {
    const first = sum();
    if (!(token.type === 'operator' && COMPARISONS.has(token.value))) return first;
    const operands = [first];
    const operators = [];
    while (token.type === 'operator' && COMPARISONS.has(token.value)) {
      operators.push(take());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

  // sum := product (('+' | '-') product)*
  function sum() {
    let left = product();
    while (isOperator('+') || isOperator('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  // product := unary (('*' | '/' | '//' | '%') unary)*
  function product() {
    let left = unary();
    while (token.type === 'operator' && PRODUCTS.has(token.value)) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  // unary := ('+' | '-') unary | power  — signs collected iteratively.
  function unary() {
    const signs = [];
    while (isOperator('+') || isOperator('-')) signs.push(take());
    let node = power();
    for (let i = signs.length - 1; i >= 0; i -= 1) {
      node = { type: 'unary', operator: signs[i], operand: node };
    }
    return node;
  }

  // power := primary ('**' unary)?  — right-associative via unary.
  function power() {
    const base = primary();
    if (!isOperator('**')) return base;
    const operator = take();
    return binary(operator, base, unary());
  }

  function call(name) {
    if (!BUILTINS.has(name.value)) throw new ExprError('Unknown function', name.column);
    take(); // '('
    if (isOperator(')')) throw new ExprError('Wrong argument count', name.column);
    const args = [comparison()];
    while (isOperator(',')) {
      if (name.value === 'abs') throw new ExprError('Wrong argument count', name.column);
      take();
      args.push(comparison());
    }
    expect(')');
    return { type: 'call', name: name.value, args };
  }

  function primary() {
    if (token.type === 'number') return { type: 'number', value: take().value };
    if (token.type === 'identifier') {
      const name = take();
      if (isOperator('(')) return call(name);
      return { type: 'variable', name: name.value, column: name.column };
    }
    if (isOperator('(')) {
      take();
      const expression = comparison();
      expect(')');
      return expression;
    }
    throw new ExprError('Expected an expression', token.column);
  }

  const expression = comparison();
  if (token.type !== 'eof') throw new ExprError('Unexpected token', token.column);
  return expression;
}

module.exports = { parse };

