'use strict';

const { ExprError } = require('./errors');

/** Python float floor division (CPython float_floor_div); zero results are +0. */
function floorDivide(left, right) {
  const mod = left % right;
  let div = (left - mod) / right;
  if (mod !== 0 && (right < 0) !== (mod < 0)) div -= 1;
  if (div === 0) return 0;
  let floored = Math.floor(div);
  if (div - floored > 0.5) floored += 1;
  return floored === 0 ? 0 : floored;
}

/** Python modulo: result takes the divisor's sign; zero results are +0. */
function modulo(left, right) {
  let mod = left % right;
  if (mod === 0) return 0;
  if ((right < 0) !== (mod < 0)) mod += right;
  return mod === 0 ? 0 : mod;
}

/** Python pow for the cases where JavaScript's ** differs (1 ** nan, (-1) ** inf). */
function power(left, right) {
  if (left === 1) return 1;
  if (left === -1 && (right === Infinity || right === -Infinity)) return 1;
  return left ** right;
}

